+func splitVirtualPath(name string) []string {
+	switch name {
+	case "", ".", "/":
+		return nil
+	}
+	name = strings.TrimPrefix(name, "/")
+	if name == "" {
+		return nil
+	}
+	return strings.Split(name, "/")
+}
+
+func joinVirtualPath(base string, segments []string) string {
+	for _, segment := range segments {
